    'num', num, 'status',
      CASE WHEN present IS NULL THEN 'UNPROBEABLE' WHEN present THEN 'PRESENT' ELSE 'MISSING' END,
    'how', how, 'file_name', file_name, 'looked_for', looked_for
  ) ORDER BY num)) AS section_2_every_migration
FROM probes;

